<x-app-layout><x-slot name="header"><h2 class="font-semibold text-xl">My villa bookings</h2></x-slot><main class="max-w-4xl mx-auto p-6 space-y-4">@if(session('status'))<p role="status">{{ session('status') }}</p>@endif @if($errors->any())<p role="alert" class="text-red-700">{{ $errors->first() }}</p>@endif @forelse($reservations as $r)<article class="bg-white rounded shadow p-5"><h3 class="font-bold">{{ $r->villa->name }} · {{ ucfirst($r->status) }}</h3><p>Reference: {{ $r->reference }} · {{ $r->check_in->toDateString() }} to {{ $r->check_out->toDateString() }} · {{ $r->guests }} guests · ${{ number_format($r->total_price,2) }}</p>@if($r->status==='confirmed' && $r->check_in->isFuture())<form method="post" action="{{ route('reservations.cancel',$r) }}">@csrf @method('PATCH')<button class="mt-2 text-red-700 underline">Cancel booking</button></form>@endif @if($r->status==='completed' && $r->check_out->isPast() && !$r->review)<form method="post" action="{{ route('reservations.review',$r) }}" class="mt-3 flex flex-wrap gap-2">@csrf<select required name="rating" aria-label="Rating" class="border rounded"><option value="">Rate stay</option>@for($i=5;$i>=1;$i--)<option value="{{ $i }}">{{ $i }} stars</option>@endfor</select><input name="comment" maxlength="1000" placeholder="Review (optional)" class="border rounded p-2"><button class="underline">Submit review</button></form>@elseif($r->review)<p class="mt-2">Your review: {{ $r->review->rating }}/5 — {{ $r->review->comment }}</p>@endif</article>@empty<p>No bookings yet.</p>@endforelse</main></x-app-layout>